```ts
// pytest short-summary lines: `FAILED <nodeid> - <repr>` and, for collection
// failures, `ERROR <nodeid-or-path>`. The nodeid runs up to the ` - ` repr
// separator (space-hyphen-space) or end of line — but a parametrized nodeid
// can itself contain ` - ` inside its [params] bracket (e.g. `test_p[a - b]`),
// and truncating there would collapse `test_p[a - b]` and `test_p[a - c]` into
// one id, hiding a new regression behind a pre-existing failure in the sibling
// param. So the separator is the first ` - ` found at bracket depth zero: the
// [params] section is kept verbatim, which keeps distinct nodeids distinct and
// each id identical across runs (only the repr, the part that can differ
// between runs of the same failing test, is dropped).
const PYTEST_LINE = /^(?:FAILED|ERROR)\s+(.+)$/;
const PYTEST_REPR_SEP = ' - ';

// Truncate a pytest short-summary field at the first ` - ` repr separator that
// is not inside a [parametrization] bracket. If no depth-zero separator is
// found (e.g. an unbalanced `[` inside a param value), the whole field is
// kept: that can over-split ids across runs, which only ever makes the gate
// blame the diff — parse gaps never make the gate lenient.
function stripPytestRepr(field: string): string {
  let depth = 0;
  for (let i = 0; i < field.length; i++) {
    const ch = field[i];
    if (ch === '[') depth++;
    else if (ch === ']') {
      if (depth > 0) depth--;
    } else if (depth === 0 && ch === ' ' && field.startsWith(PYTEST_REPR_SEP, i)) {
      return field.slice(0, i).trim();
    }
  }
  return field;
}

function addPytestIds(text: string, ids: Set<string>): void {
  for (const raw of text.split('\n')) {
    const m = raw.trim().match(PYTEST_LINE);
    if (!m) continue;
    const nodeid = stripPytestRepr(m[1]!.trim());
    if (nodeid) ids.add(nodeid);
  }
}
```

