// pytest short-summary lines: `FAILED <nodeid> - <repr>` and, for collection
// failures, `ERROR <nodeid-or-path>`. The nodeid runs up to the ` - ` repr
// separator (space-hyphen-space) or end of line — but a parametrized nodeid
// can contain its own ` - ` inside the trailing `[params]` bracket
// (`test_p[a - b]`), and truncating there would collapse `test_p[a - b]` and
// `test_p[a - c]` into one id, hiding a new regression behind a pre-existing
// failure in the sibling param. So the separator is the first ` - ` at bracket
// depth zero: `[params]` is kept verbatim, which keeps distinct nodeids
// distinct while still dropping only the repr — the one part that can differ
// between runs of the same failing test — so ids stay stable across runs.
const PYTEST_LINE = /^(?:FAILED|ERROR)\s+(.+)$/;
const PYTEST_REPR_SEP = ' - ';

// Cut a pytest summary field at the first ` - ` separator that is not inside a
// `[parametrization]` bracket. If none is found (e.g. an unbalanced `[` inside
// a param value keeps the depth open), the whole field is kept: that can split
// one test into run-specific ids, which only ever makes the delta report MORE
// new failures — parse gaps never make the gate lenient.
function stripPytestRepr(field: string): string {
  let depth = 0;
  for (let i = 0; i < field.length; i++) {
    const ch = field[i];
    if (ch === '[') depth++;
    else if (ch === ']') {
      if (depth > 0) depth--;
    } else if (depth === 0 && ch === ' ' && field.startsWith(PYTEST_REPR_SEP, i)) {
      return field.slice(0, i).trim();
    }
  }
  return field;
}

function addPytestIds(text: string, ids: Set<string>): void {
  for (const raw of text.split('\n')) {
    const m = raw.trim().match(PYTEST_LINE);
    if (!m) continue;
    const nodeid = stripPytestRepr(m[1]!.trim());
    if (nodeid) ids.add(nodeid);
  }
}

