1	// tests/unit/verify/runner-env-redaction.test.ts
2	//
3	// SEC-3. The tests gate spawns the repository's own test suite - code supplied
4	// by the diff under verification - and handed it `{...process.env}`. In the
5	// deployment this product is sold for, a CI gate verifying an untrusted pull
6	// request, that environment is full of credentials.
7	//
8	// Reproduced before the fix: a test in the verified suite read
9	// REFACTRON_TOKEN, GITHUB_TOKEN, NPM_TOKEN and AWS_SECRET_ACCESS_KEY in
10	// plaintext.
11	//
12	// A denylist, not an allowlist: real suites need HOME, PATH, LANG and a long
